package com.yeyamo_mobile.api.partner_service.interfaces.rest;
import java.time.Instant;import java.util.UUID;import java.util.Set;import com.yeyamo_mobile.api.partner_service.domain.model.*;
public record PartnerResponse(UUID id,String legalName,String tradeName,BusinessType businessType,String registrationNumber,String taxId,String contactEmail,String contactPhone,String websiteUrl,String description,String primaryCountryCode,Set<String> operatingCountries,PartnerStatus status,String reviewComment,Integer riskScore,Instant submittedAt,Instant verifiedAt,Instant createdAt,Instant updatedAt){public static PartnerResponse from(Partner p){return new PartnerResponse(p.getId(),p.getLegalName(),p.getTradeName(),p.getBusinessType(),p.getRegistrationNumber(),p.getTaxId(),p.getContactEmail(),p.getContactPhone(),p.getWebsiteUrl(),p.getDescription(),p.getPrimaryCountryCode(),p.getOperatingCountries(),p.getStatus(),p.getReviewComment(),p.getRiskScore(),p.getSubmittedAt(),p.getVerifiedAt(),p.getCreatedAt(),p.getUpdatedAt());}}
